mapper.select:
SELECT FROM gw_board_post p JOIN gw_board b ON b.board_id = p.board_id LEFT JOIN gw_user u ON u.user_id = p.author_id LEFT JOIN gw_dept d ON d.dept_id = u.dept_id WHERE p.deleted_at IS NULL AND p.board_id = #{boardId}
AND (LOWER(p.title) LIKE LOWER('%' || #{keyword} || '%') OR LOWER(p.content) LIKE LOWER('%' || #{keyword} || '%'))
ORDER BY p.pinned_yn DESC, p.created_at DESC LIMIT #{limit} OFFSET #{offset}

mapper.update:
UPDATE gw_board_comment SET deleted_at = CURRENT_TIMESTAMP
 WHERE cmt_id = #{cmtId}
   AND (author_id = #{authorId} OR #{roleCd} IN ('ADMIN','HR_MANAGER'))
